//! A from-scratch, dependency-free port of the earcut polygon triangulation
//! algorithm.
//!
//! Input is a polygon given as a list of rings — the first ring is the outer
//! contour, any remaining rings are holes. Output is a flat list of triangle
//! vertex indices into the concatenated ring coordinates.

pub mod geom;
pub mod node;
pub mod triangulate;
pub mod zorder;

pub use self::triangulate::Earcut;

/// Triangulates `polygon` and returns the triangle index list.
pub fn earcut<R: AsRef<[[f64; 2]]>>(polygon: &[R]) -> Vec<u32> {
    let mut ec = Earcut::new();
    ec.run(polygon);
    ec.indices
}

//! Ear clipping triangulator.
//!
//! Straight port of the classic earcut algorithm: build circular doubly linked
//! rings from the input, splice holes into the outer ring, then repeatedly clip
//! ears, falling back through progressively more aggressive repair passes
//! (`filterPoints`, local self-intersection curing, diagonal splitting) when no
//! ear can be found.
//!
//! Control flow, comparison boundaries and emission order follow the reference
//! exactly, because the triangle index sequence is observable output.

use super::geom::{
    area, equals, intersects, locally_inside, middle_inside, point_in_triangle,
    sector_contains_sector,
};
use super::node::{Arena, NIL};
use super::zorder::z_order;

/// A polygon: the first ring is the outer contour, the rest are holes.
pub type Ring = [[f64; 2]];

pub struct Earcut {
    nodes: Arena,
    pub indices: Vec<u32>,
    vertices: usize,

    hashing: bool,
    min_x: f64,
    max_x: f64,
    min_y: f64,
    max_y: f64,
    inv_size: f64,
}

impl Earcut {
    pub fn new() -> Earcut {
        Earcut {
            nodes: Arena::new(),
            indices: Vec::new(),
            vertices: 0,
            hashing: false,
            min_x: 0.0,
            max_x: 0.0,
            min_y: 0.0,
            max_y: 0.0,
            inv_size: 0.0,
        }
    }

    /// Triangulates a polygon, filling `indices` with triangle vertex indices
    /// referring to the flattened input coordinate sequence.
    pub fn run<R: AsRef<Ring>>(&mut self, points: &[R]) {
        // reset
        self.indices.clear();
        self.vertices = 0;
        self.nodes.clear();

        if points.is_empty() {
            return;
        }

        let mut threshold: i32 = 80;
        let mut len: usize = 0;

        let mut i = 0;
        while threshold >= 0 && i < points.len() {
            threshold -= points[i].as_ref().len() as i32;
            len += points[i].as_ref().len();
            i += 1;
        }

        // estimate size of nodes and indices
        self.nodes.reserve(len * 3 / 2);
        self.indices.reserve(len + points[0].as_ref().len());

        let mut outer_node = self.linked_list(points[0].as_ref(), true);
        if outer_node == NIL || self.nodes[outer_node].prev == self.nodes[outer_node].next {
            return;
        }

        if points.len() > 1 {
            outer_node = self.eliminate_holes(points, outer_node);
        }

        // if the shape is not too simple, we'll use z-order curve hash later;
        // calculate polygon bbox
        self.hashing = threshold < 0;
        if self.hashing {
            let mut p = self.nodes[outer_node].next;
            self.min_x = self.nodes[outer_node].x;
            self.max_x = self.min_x;
            self.min_y = self.nodes[outer_node].y;
            self.max_y = self.min_y;
            loop {
                let x = self.nodes[p].x;
                let y = self.nodes[p].y;
                self.min_x = self.min_x.min(x);
                self.min_y = self.min_y.min(y);
                self.max_x = self.max_x.max(x);
                self.max_y = self.max_y.max(y);
                p = self.nodes[p].next;
                if p == outer_node {
                    break;
                }
            }

            // min_x, min_y and inv_size are later used to transform coords into
            // integers for z-order calculation
            self.inv_size = (self.max_x - self.min_x).max(self.max_y - self.min_y);
            self.inv_size = if self.inv_size != 0.0 {
                32767.0 / self.inv_size
            } else {
                0.0
            };
        }

        self.earcut_linked(outer_node, 0);
    }

    /// Creates a circular doubly linked list from polygon points in the
    /// specified winding order.
    fn linked_list(&mut self, points: &Ring, clockwise: bool) -> usize {
        let mut sum = 0.0;
        let len = points.len();
        let mut last = NIL;

        // calculate original winding order of a polygon ring
        let mut j = if len > 0 { len - 1 } else { 0 };
        for i in 0..len {
            let p1 = &points[i];
            let p2 = &points[j];
            let p20 = p2[0];
            let p10 = p1[0];
            let p11 = p1[1];
            let p21 = p2[1];
            sum += (p20 - p10) * (p11 + p21);
            j = i;
        }

        // link points into circular doubly-linked list in the specified winding
        // order
        if clockwise == (sum > 0.0) {
            for i in 0..len {
                last = self.insert_node(self.vertices + i, points[i], last);
            }
        } else {
            for i in (0..len).rev() {
                last = self.insert_node(self.vertices + i, points[i], last);
            }
        }

        if last != NIL && equals(self.nodes.as_slice(), last, self.nodes[last].next) {
            self.remove_node(last);
            last = self.nodes[last].next;
        }

        self.vertices += len;

        last
    }

    /// Eliminates colinear or duplicate points.
    fn filter_points(&mut self, start: usize, end: usize) -> usize {
        if start == NIL {
            return start;
        }
        let mut end = if end == NIL { start } else { end };

        let mut p = start;
        let mut again;
        loop {
            again = false;

            let (prev, next) = (self.nodes[p].prev, self.nodes[p].next);
            if !self.nodes[p].steiner
                && (equals(self.nodes.as_slice(), p, next)
                    || area(self.nodes.as_slice(), prev, p, next) == 0.0)
            {
                self.remove_node(p);
                p = self.nodes[p].prev;
                end = p;

                if p == self.nodes[p].next {
                    break;
                }
                again = true;
            } else {
                p = self.nodes[p].next;
            }

            if !(again || p != end) {
                break;
            }
        }

        end
    }

    /// Main ear slicing loop which triangulates a polygon (given as a linked
    /// list).
    fn earcut_linked(&mut self, ear_in: usize, pass: i32) {
        if ear_in == NIL {
            return;
        }
        let mut ear = ear_in;

        // interlink polygon nodes in z-order
        if pass == 0 && self.hashing {
            self.index_curve(ear);
        }

        let mut stop = ear;

        // iterate through ears, slicing them one by one
        while self.nodes[ear].prev != self.nodes[ear].next {
            let prev = self.nodes[ear].prev;
            let next = self.nodes[ear].next;

            let is_ear = if self.hashing {
                self.is_ear_hashed(ear)
            } else {
                self.is_ear(ear)
            };

            if is_ear {
                // cut off the triangle
                self.indices.push(self.nodes[prev].i);
                self.indices.push(self.nodes[ear].i);
                self.indices.push(self.nodes[next].i);

                self.remove_node(ear);

                // skipping the next vertex leads to less sliver triangles
                ear = self.nodes[next].next;
                stop = self.nodes[next].next;

                continue;
            }

            ear = next;

            // if we looped through the whole remaining polygon and can't find
            // any more ears
            if ear == stop {
                // try filtering points and slicing again
                if pass == 0 {
                    let filtered = self.filter_points(ear, NIL);
                    self.earcut_linked(filtered, 1);
                } else if pass == 1 {
                    // if this didn't work, try curing all small
                    // self-intersections locally
                    let filtered = self.filter_points(ear, NIL);
                    let cured = self.cure_local_intersections(filtered);
                    self.earcut_linked(cured, 2);
                } else if pass == 2 {
                    // as a last resort, try splitting the remaining polygon
                    // into two
                    self.split_earcut(ear);
                }

                break;
            }
        }
    }

    /// Checks whether a polygon node forms a valid ear with adjacent nodes.
    fn is_ear(&self, ear: usize) -> bool {
        let nodes = self.nodes.as_slice();
        let a = nodes[ear].prev;
        let b = ear;
        let c = nodes[ear].next;

        if area(nodes, a, b, c) >= 0.0 {
            return false; // reflex, can't be an ear
        }

        // now make sure we don't have other points inside the potential ear
        let mut p = nodes[nodes[ear].next].next;

        while p != nodes[ear].prev {
            if point_in_triangle(
                nodes[a].x, nodes[a].y, nodes[b].x, nodes[b].y, nodes[c].x, nodes[c].y, nodes[p].x,
                nodes[p].y,
            ) && area(nodes, nodes[p].prev, p, nodes[p].next) >= 0.0
            {
                return false;
            }
            p = nodes[p].next;
        }

        true
    }

    /// Same as `is_ear`, but only inspects candidates whose Morton code falls
    /// in the triangle's bounding box range.
    fn is_ear_hashed(&self, ear: usize) -> bool {
        let nodes = self.nodes.as_slice();
        let a = nodes[ear].prev;
        let b = ear;
        let c = nodes[ear].next;

        if area(nodes, a, b, c) >= 0.0 {
            return false; // reflex, can't be an ear
        }

        // triangle bbox; min & max are calculated like this for speed
        let min_tx = nodes[a].x.min(nodes[b].x.min(nodes[c].x));
        let min_ty = nodes[a].y.min(nodes[b].y.min(nodes[c].y));
        let max_tx = nodes[a].x.max(nodes[b].x.max(nodes[c].x));
        let max_ty = nodes[a].y.max(nodes[b].y.max(nodes[c].y));

        // z-order range for the current triangle bbox
        let min_z = self.z_order(min_tx, min_ty);
        let max_z = self.z_order(max_tx, max_ty);

        // first look for points inside the triangle in increasing z-order
        let mut p = nodes[ear].prev_z;
        let mut n = nodes[ear].next_z;

        while p != NIL && nodes[p].z >= min_z && n != NIL && nodes[n].z <= max_z {
            if nodes[p].x >= min_tx
                && nodes[p].x <= max_tx
                && nodes[p].y >= min_ty
                && nodes[p].y <= max_ty
                && p != a
                && p != c
                && point_in_triangle(
                    nodes[a].x, nodes[a].y, nodes[b].x, nodes[b].y, nodes[c].x, nodes[c].y,
                    nodes[p].x, nodes[p].y,
                )
                && area(nodes, nodes[p].prev, p, nodes[p].next) >= 0.0
            {
                return false;
            }
            p = nodes[p].prev_z;

            if nodes[n].x >= min_tx
                && nodes[n].x <= max_tx
                && nodes[n].y >= min_ty
                && nodes[n].y <= max_ty
                && n != a
                && n != c
                && point_in_triangle(
                    nodes[a].x, nodes[a].y, nodes[b].x, nodes[b].y, nodes[c].x, nodes[c].y,
                    nodes[n].x, nodes[n].y,
                )
                && area(nodes, nodes[n].prev, n, nodes[n].next) >= 0.0
            {
                return false;
            }
            n = nodes[n].next_z;
        }

        // look for remaining points in decreasing z-order
        while p != NIL && nodes[p].z >= min_z {
            if nodes[p].x >= min_tx
                && nodes[p].x <= max_tx
                && nodes[p].y >= min_ty
                && nodes[p].y <= max_ty
                && p != a
                && p != c
                && point_in_triangle(
                    nodes[a].x, nodes[a].y, nodes[b].x, nodes[b].y, nodes[c].x, nodes[c].y,
                    nodes[p].x, nodes[p].y,
                )
                && area(nodes, nodes[p].prev, p, nodes[p].next) >= 0.0
            {
                return false;
            }
            p = nodes[p].prev_z;
        }

        // look for remaining points in increasing z-order
        while n != NIL && nodes[n].z <= max_z {
            if nodes[n].x >= min_tx
                && nodes[n].x <= max_tx
                && nodes[n].y >= min_ty
                && nodes[n].y <= max_ty
                && n != a
                && n != c
                && point_in_triangle(
                    nodes[a].x, nodes[a].y, nodes[b].x, nodes[b].y, nodes[c].x, nodes[c].y,
                    nodes[n].x, nodes[n].y,
                )
                && area(nodes, nodes[n].prev, n, nodes[n].next) >= 0.0
            {
                return false;
            }
            n = nodes[n].next_z;
        }

        true
    }

    /// Goes through all polygon nodes and cures small local self-intersections.
    fn cure_local_intersections(&mut self, start_in: usize) -> usize {
        let mut start = start_in;
        let mut p = start;
        loop {
            let a = self.nodes[p].prev;
            let pn = self.nodes[p].next;
            let b = self.nodes[pn].next;

            if !equals(self.nodes.as_slice(), a, b)
                && intersects(self.nodes.as_slice(), a, p, pn, b)
                && locally_inside(self.nodes.as_slice(), a, b)
                && locally_inside(self.nodes.as_slice(), b, a)
            {
                self.indices.push(self.nodes[a].i);
                self.indices.push(self.nodes[p].i);
                self.indices.push(self.nodes[b].i);

                // remove two nodes involved
                self.remove_node(p);
                let next = self.nodes[p].next;
                self.remove_node(next);

                p = b;
                start = b;
            }
            p = self.nodes[p].next;
            if p == start {
                break;
            }
        }

        self.filter_points(p, NIL)
    }

    /// Tries splitting polygon into two and triangulating them independently.
    fn split_earcut(&mut self, start: usize) {
        // look for a valid diagonal that divides the polygon into two
        let mut a = start;
        loop {
            let mut b = self.nodes[self.nodes[a].next].next;
            while b != self.nodes[a].prev {
                if self.nodes[a].i != self.nodes[b].i && self.is_valid_diagonal(a, b) {
                    // split the polygon in two by the diagonal
                    let mut c = self.split_polygon(a, b);

                    // filter colinear points around the cuts
                    let a_next = self.nodes[a].next;
                    a = self.filter_points(a, a_next);
                    let c_next = self.nodes[c].next;
                    c = self.filter_points(c, c_next);

                    // run earcut on each half
                    self.earcut_linked(a, 0);
                    self.earcut_linked(c, 0);
                    return;
                }
                b = self.nodes[b].next;
            }
            a = self.nodes[a].next;
            if a == start {
                break;
            }
        }
    }

    /// Links every hole into the outer loop, producing a single-ring polygon.
    fn eliminate_holes<R: AsRef<Ring>>(&mut self, points: &[R], outer_node_in: usize) -> usize {
        let mut outer_node = outer_node_in;
        let len = points.len();

        let mut queue: Vec<usize> = Vec::new();
        for i in 1..len {
            let list = self.linked_list(points[i].as_ref(), false);
            if list != NIL {
                if list == self.nodes[list].next {
                    self.nodes[list].steiner = true;
                }
                queue.push(self.get_leftmost(list));
            }
        }

        let xs: Vec<f64> = queue.iter().map(|&q| self.nodes[q].x).collect();
        let mut order: Vec<usize> = (0..queue.len()).collect();
        order.sort_by(|&l, &r| xs[l].partial_cmp(&xs[r]).unwrap_or(std::cmp::Ordering::Equal));
        let queue: Vec<usize> = order.into_iter().map(|k| queue[k]).collect();

        // process holes from left to right
        for &hole in queue.iter() {
            outer_node = self.eliminate_hole(hole, outer_node);
        }

        outer_node
    }

    /// Finds a bridge between vertices that connects a hole with an outer ring,
    /// and links it.
    fn eliminate_hole(&mut self, hole: usize, outer_node: usize) -> usize {
        let bridge = self.find_hole_bridge(hole, outer_node);
        if bridge == NIL {
            return outer_node;
        }

        let bridge_reverse = self.split_polygon(bridge, hole);

        // filter collinear points around the cuts
        let br_next = self.nodes[bridge_reverse].next;
        self.filter_points(bridge_reverse, br_next);
        let b_next = self.nodes[bridge].next;
        self.filter_points(bridge, b_next)
    }

    /// David Eberly's algorithm for finding a bridge between hole and outer
    /// polygon.
    fn find_hole_bridge(&self, hole: usize, outer_node: usize) -> usize {
        let nodes = self.nodes.as_slice();
        let mut p = outer_node;
        let hx = nodes[hole].x;
        let hy = nodes[hole].y;
        let mut qx = f64::NEG_INFINITY;
        let mut m = NIL;

        // find a segment intersected by a ray from the hole's leftmost vertex
        // to the left; segment's endpoint with lesser x will be potential
        // connection vertex
        loop {
            let pn = nodes[p].next;
            if hy <= nodes[p].y && hy >= nodes[pn].y && nodes[pn].y != nodes[p].y {
                let x = nodes[p].x
                    + (hy - nodes[p].y) * (nodes[pn].x - nodes[p].x)
                        / (nodes[pn].y - nodes[p].y);
                if x <= hx && x > qx {
                    qx = x;
                    m = if nodes[p].x < nodes[pn].x { p } else { pn };
                    if x == hx {
                        // hole touches outer segment; pick leftmost endpoint
                        return m;
                    }
                }
            }
            p = pn;
            if p == outer_node {
                break;
            }
        }

        if m == NIL {
            return NIL;
        }

        // look for points inside the triangle of hole vertex, segment
        // intersection and endpoint; if there are no points found, we have a
        // valid connection; otherwise choose the vertex of the minimum angle
        // with the ray as connection vertex
        let stop = m;
        let mut tan_min = f64::INFINITY;

        p = m;
        let mx = nodes[m].x;
        let my = nodes[m].y;

        loop {
            if hx >= nodes[p].x
                && nodes[p].x >= mx
                && hx != nodes[p].x
                && point_in_triangle(
                    if hy < my { hx } else { qx },
                    hy,
                    mx,
                    my,
                    if hy < my { qx } else { hx },
                    hy,
                    nodes[p].x,
                    nodes[p].y,
                )
            {
                let tan_cur = (hy - nodes[p].y).abs() / (hx - nodes[p].x); // tangential

                if locally_inside(nodes, p, hole)
                    && (tan_cur < tan_min
                        || (tan_cur == tan_min
                            && (nodes[p].x > nodes[m].x || sector_contains_sector(nodes, m, p))))
                {
                    m = p;
                    tan_min = tan_cur;
                }
            }

            p = nodes[p].next;
            if p == stop {
                break;
            }
        }

        m
    }

    /// Interlinks polygon nodes in z-order.
    fn index_curve(&mut self, start: usize) {
        let mut p = start;

        loop {
            if self.nodes[p].z == 0 {
                let (x, y) = (self.nodes[p].x, self.nodes[p].y);
                self.nodes[p].z = self.z_order(x, y);
            }
            self.nodes[p].prev_z = self.nodes[p].prev;
            self.nodes[p].next_z = self.nodes[p].next;
            p = self.nodes[p].next;
            if p == start {
                break;
            }
        }

        let pz = self.nodes[p].prev_z;
        self.nodes[pz].next_z = NIL;
        self.nodes[p].prev_z = NIL;

        self.sort_linked(p);
    }

    /// Simon Tatham's linked list merge sort algorithm, applied to the z-order
    /// list.
    fn sort_linked(&mut self, list_in: usize) -> usize {
        let mut list = list_in;
        let mut in_size: i32 = 1;

        loop {
            let mut p = list;
            list = NIL;
            let mut tail = NIL;
            let mut num_merges = 0;

            while p != NIL {
                num_merges += 1;
                let mut q = p;
                let mut p_size = 0;
                for _ in 0..in_size {
                    p_size += 1;
                    q = self.nodes[q].next_z;
                    if q == NIL {
                        break;
                    }
                }

                let mut q_size = in_size;

                while p_size > 0 || (q_size > 0 && q != NIL) {
                    let e;
                    if p_size == 0 {
                        e = q;
                        q = self.nodes[q].next_z;
                        q_size -= 1;
                    } else if q_size == 0 || q == NIL {
                        e = p;
                        p = self.nodes[p].next_z;
                        p_size -= 1;
                    } else if self.nodes[p].z <= self.nodes[q].z {
                        e = p;
                        p = self.nodes[p].next_z;
                        p_size -= 1;
                    } else {
                        e = q;
                        q = self.nodes[q].next_z;
                        q_size -= 1;
                    }

                    if tail != NIL {
                        self.nodes[tail].next_z = e;
                    } else {
                        list = e;
                    }

                    self.nodes[e].prev_z = tail;
                    tail = e;
                }

                p = q;
            }

            self.nodes[tail].next_z = NIL;

            if num_merges <= 1 {
                return list;
            }

            in_size *= 2;
        }
    }

    /// Finds the leftmost node of a polygon ring.
    fn get_leftmost(&self, start: usize) -> usize {
        let nodes = self.nodes.as_slice();
        let mut p = start;
        let mut leftmost = start;
        loop {
            if nodes[p].x < nodes[leftmost].x
                || (nodes[p].x == nodes[leftmost].x && nodes[p].y < nodes[leftmost].y)
            {
                leftmost = p;
            }
            p = nodes[p].next;
            if p == start {
                break;
            }
        }

        leftmost
    }

    /// Checks if a diagonal between two polygon nodes is valid (lies in polygon
    /// interior).
    fn is_valid_diagonal(&self, a: usize, b: usize) -> bool {
        let nodes = self.nodes.as_slice();
        nodes[nodes[a].next].i != nodes[b].i
            && nodes[nodes[a].prev].i != nodes[b].i
            && !self.intersects_polygon(a, b) // doesn't intersect other edges
            && ((locally_inside(nodes, a, b)
                && locally_inside(nodes, b, a)
                && middle_inside(nodes, a, b) // locally visible
                // does not create opposite-facing sectors
                && (area(nodes, nodes[a].prev, a, nodes[b].prev) != 0.0
                    || area(nodes, a, nodes[b].prev, b) != 0.0))
                // special zero-length case
                || (equals(nodes, a, b)
                    && area(nodes, nodes[a].prev, a, nodes[a].next) > 0.0
                    && area(nodes, nodes[b].prev, b, nodes[b].next) > 0.0))
    }

    /// Checks if a polygon diagonal intersects any polygon segments.
    fn intersects_polygon(&self, a: usize, b: usize) -> bool {
        let nodes = self.nodes.as_slice();
        let mut p = a;
        loop {
            let pn = nodes[p].next;
            if nodes[p].i != nodes[a].i
                && nodes[pn].i != nodes[a].i
                && nodes[p].i != nodes[b].i
                && nodes[pn].i != nodes[b].i
                && intersects(nodes, p, pn, a, b)
            {
                return true;
            }
            p = pn;
            if p == a {
                break;
            }
        }

        false
    }

    /// Links two polygon vertices with a bridge; if the vertices belong to the
    /// same ring, it splits the polygon into two.
    fn split_polygon(&mut self, a: usize, b: usize) -> usize {
        let a2 = self
            .nodes
            .create(self.nodes[a].i, self.nodes[a].x, self.nodes[a].y);
        let b2 = self
            .nodes
            .create(self.nodes[b].i, self.nodes[b].x, self.nodes[b].y);
        let an = self.nodes[a].next;
        let bp = self.nodes[b].prev;

        self.nodes[a].next = b;
        self.nodes[b].prev = a;

        self.nodes[a2].next = an;
        self.nodes[an].prev = a2;

        self.nodes[b2].next = a2;
        self.nodes[a2].prev = b2;

        self.nodes[bp].next = b2;
        self.nodes[b2].prev = bp;

        b2
    }

    /// Creates a node and optionally links it with the previous one (in a
    /// circular doubly linked list).
    fn insert_node(&mut self, i: usize, pt: [f64; 2], last: usize) -> usize {
        let p = self.nodes.create(i as u32, pt[0], pt[1]);

        if last == NIL {
            self.nodes[p].prev = p;
            self.nodes[p].next = p;
        } else {
            let ln = self.nodes[last].next;
            self.nodes[p].next = ln;
            self.nodes[p].prev = last;
            self.nodes[ln].prev = p;
            self.nodes[last].next = p;
        }
        p
    }

    /// Unlinks a node from both the ring and the z-order list. The node keeps
    /// its own `prev`/`next`, exactly like the pointer-based original.
    fn remove_node(&mut self, p: usize) {
        let (prev, next) = (self.nodes[p].prev, self.nodes[p].next);
        self.nodes[next].prev = prev;
        self.nodes[prev].next = next;

        let (prev_z, next_z) = (self.nodes[p].prev_z, self.nodes[p].next_z);
        if prev_z != NIL {
            self.nodes[prev_z].next_z = next_z;
        }
        if next_z != NIL {
            self.nodes[next_z].prev_z = prev_z;
        }
    }

    fn z_order(&self, x: f64, y: f64) -> i32 {
        z_order(x, y, self.min_x, self.min_y, self.inv_size)
    }
}

impl Default for Earcut {
    fn default() -> Earcut {
        Earcut::new()
    }
